CREATE TABLE IF NOT EXISTS usuarios (id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL UNIQUE COLLATE NOCASE, email TEXT UNIQUE COLLATE NOCASE, senha TEXT NOT NULL DEFAULT '', verificado INTEGER NOT NULL DEFAULT 0, google TEXT UNIQUE, criado INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessoes (hash TEXT PRIMARY KEY, usuario INTEGER NOT NULL, expira INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS saves (usuario INTEGER PRIMARY KEY, estado TEXT NOT NULL, patrimonio REAL NOT NULL DEFAULT 0, atualizado INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS codigos (email TEXT NOT NULL, tipo TEXT NOT NULL, hash TEXT NOT NULL, expira INTEGER NOT NULL, tentativas INTEGER NOT NULL DEFAULT 0, enviado INTEGER NOT NULL, PRIMARY KEY (email, tipo));
CREATE TABLE IF NOT EXISTS falhas (chave TEXT NOT NULL, quando INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_falhas ON falhas(chave, quando);
CREATE INDEX IF NOT EXISTS idx_saves_pat ON saves(patrimonio DESC);
CREATE TABLE IF NOT EXISTS partidas (codigo TEXT PRIMARY KEY, modo TEXT NOT NULL, criador INTEGER NOT NULL, cfg TEXT NOT NULL, estado TEXT NOT NULL, criada INTEGER NOT NULL, inicio INTEGER, fim INTEGER, bots INTEGER NOT NULL DEFAULT 0, resultado TEXT);
CREATE TABLE IF NOT EXISTS partida_jog (codigo TEXT NOT NULL, usuario INTEGER NOT NULL, estado TEXT, patrimonio REAL NOT NULL DEFAULT 0, atualizado INTEGER NOT NULL DEFAULT 0, taxa INTEGER NOT NULL DEFAULT 0, premio INTEGER NOT NULL DEFAULT 0, pago INTEGER NOT NULL DEFAULT 0, entrou INTEGER NOT NULL, PRIMARY KEY (codigo, usuario));
CREATE INDEX IF NOT EXISTS idx_pj_usuario ON partida_jog(usuario, entrou DESC);
CREATE INDEX IF NOT EXISTS idx_partidas_estado ON partidas(estado, fim);
CREATE TABLE IF NOT EXISTS perfis (usuario INTEGER PRIMARY KEY, apelido TEXT COLLATE NOCASE, avatar TEXT NOT NULL DEFAULT 'a1', faixa TEXT, apelido_em INTEGER NOT NULL DEFAULT 0, criado INTEGER NOT NULL DEFAULT 0, moldura TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX IF NOT EXISTS idx_perfis_apelido ON perfis(apelido);
CREATE TABLE IF NOT EXISTS loja_itens (usuario INTEGER NOT NULL, item TEXT NOT NULL, quando INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (usuario, item));
-- coluna moldura: o Worker a cria sozinho (ALTER TABLE perfis ADD COLUMN moldura TEXT NOT NULL DEFAULT '')
